contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 newMinSum, address newLog) public {
        uint256 minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setMinSumReverted;
        c.SetMinSum(newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }

        bool setLogFileReverted;
        c.SetLogFile(newLog); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogFileReverted = true;
        } else {
            setLogFileReverted = false;
        }

        assert(setMinSumReverted && setLogFileReverted && c.MinSum() == minBefore);
    }
}

